<script setup>
import {ref,onMounted} from 'vue';import AppShell from '../components/AppShell.vue';import {supabase} from '../services/supabase';import {RouterLink} from 'vue-router';const items=ref([]),loading=ref(true);async function load(){const {data:{user}}=await supabase.auth.getUser();const {data}=await supabase.from('notifications').select('*').eq('user_id',user.id).order('created_at',{ascending:false});items.value=data||[];loading.value=false}onMounted(load);async function mark(n){await supabase.from('notifications').update({is_read:true}).eq('id',n.id);n.is_read=true}async function markAll(){const {data:{user}}=await supabase.auth.getUser();await supabase.from('notifications').update({is_read:true}).eq('user_id',user.id);items.value.forEach(n=>n.is_read=true)}
</script>
<template><AppShell title="Notifications" subtitle="Stay in the loop"><template #default><div class="page-heading"><div><span class="eyebrow">YOUR UPDATES</span><h1 class="page-title">Notifications</h1><p class="page-subtitle">Important updates about your account and opportunities.</p></div><button class="btn btn-outline" @click="markAll">Mark all as read</button></div><div v-if="loading" class="empty">Loading notifications…</div><div v-else-if="items.length" class="notification-list"><article v-for="n in items" :key="n.id" class="card notification" :class="{unread:!n.is_read}"><span class="notification-icon">{{n.type==='application'?'▣':n.type==='job'?'✦':'◉'}}</span><div class="notification-copy"><b>{{n.title}}</b><p>{{n.message}}</p><small>{{new Date(n.created_at).toLocaleString('en-ZA')}}</small><RouterLink v-if="n.link" :to="n.link" @click="mark(n)">View update →</RouterLink></div><button v-if="!n.is_read" class="mark-read" @click="mark(n)">Mark read</button></article></div><div v-else class="empty"><h3>You're all caught up</h3><p>New updates will appear here.</p></div></template></AppShell></template>
<style scoped>.page-heading{display:flex;align-items:end;justify-content:space-between;gap:15px}.notification-list{display:grid;gap:10px;margin-top:22px}.notification{display:flex;gap:14px;align-items:flex-start}.notification.unread{border-left:4px solid var(--green)}.notification-icon{width:38px;height:38px;border-radius:12px;background:var(--surface2);display:grid;place-items:center;color:var(--green);font-size:19px}.notification-copy{flex:1}.notification-copy b{font-size:14px}.notification-copy p{margin:5px 0;color:var(--muted);font-size:13px}.notification-copy small{color:var(--muted);font-size:10px}.notification-copy a{display:block;color:var(--green);font-size:12px;font-weight:700;margin-top:7px}.mark-read{border:0;background:none;color:var(--green);font-size:11px;font-weight:700}@media(max-width:600px){.page-heading{align-items:start;flex-direction:column}}</style>
